source('mp10_hypothesis_followup_v1/scripts/common.R');suppressPackageStartupMessages(library(fgsea));files<-list.files(file.path(B,'tables/treg_de'),pattern='tsv.gz$',full.names=TRUE);gs<-fread(file.path(REF,'hallmark.tsv.gz'));sets<-lapply(split(gs$gene_symbol,gs$gs_name),unique);dir.create(file.path(B,'tables/treg_gsea'),showWarnings=FALSE);out<-list();warnings<-list()
for(i in seq_along(files)){d<-fread(files[i]);id<-d$model_id[1];d[,stat:=sign(logFC)*sqrt(pmax(F,0))];d<-d[is.finite(stat)];setorder(d,-stat,gene);stats<-setNames(d$stat,d$gene);sig<-digest(list(stats,sets,123,10000,100000,15,500,1e-10),algo='sha256');f<-file.path(B,'tables/treg_gsea',paste0(id,'.tsv.gz'))
 if(file.exists(f)&&file.exists(paste0(f,'.sha256'))&&readLines(paste0(f,'.sha256'))==sig)rr<-fread(f)else{
  for(budget in c(10000,100000)){set.seed(123);ww<-character();rr<-withCallingHandlers(as.data.table(fgseaMultilevel(sets,stats,minSize=15,maxSize=500,nPermSimple=budget,eps=1e-10,nproc=1,scoreType='std')),warning=function(w){ww<<-c(ww,conditionMessage(w));invokeRestart('muffleWarning')});warnings[[paste(id,budget)]]<-data.table(model_id=id,budget=budget,warning=paste(unique(ww),collapse=' | '));if(!any(!is.finite(rr$pval)|(!is.finite(rr$log2err)&rr$pval>1e-10)))break};rr[,leadingEdge:=vapply(leadingEdge,paste,collapse=';',FUN.VALUE=character(1))];rr[,`:=`(model_id=id,celltype=d$celltype[1],setting=d$setting[1],cohort=d$cohort[1],nPermSimple=budget,n_specimens=d$n_specimens[1],n_datasets=d$n_datasets[1])];fwrite(rr,f,sep='\t',compress='gzip');writeLines(sig,paste0(f,'.sha256'))
 };out[[i]]<-rr;cat('TREG GSEA',i,length(files),id,'\n')
}
z<-rbindlist(out,fill=TRUE);z[,joint_main_q:=NA_real_];ix<-which(z$setting=='main'&z$cohort=='own');z[ix,joint_main_q:=p.adjust(pval,'BH')];put(z,'treg_decomposition_gsea.tsv.gz');if(length(warnings))put(rbindlist(warnings),'treg_decomposition_gsea_warnings.tsv');cat('TREG GSEA COMPLETE\n')
